import{_ as e,o as d,c as l,a0 as o}from"./chunks/framework.Bmhw_dvp.js";const y=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"page-5.md","filePath":"page-5.md"}'),a={name:"page-5.md"};function c(r,t,x,n,i,s){return d(),l("div",null,[...t[0]||(t[0]=[o('<h3 id="常用数学函数" tabindex="-1">常用数学函数 <a class="header-anchor" href="#常用数学函数" aria-label="Permalink to &quot;常用数学函数&quot;">​</a></h3><p><strong>注意</strong>：以下函数均定义在 <code>&lt;cmath&gt;</code> 头文件中。</p><h4 id="绝对值" tabindex="-1">绝对值 <a class="header-anchor" href="#绝对值" aria-label="Permalink to &quot;绝对值&quot;">​</a></h4><table tabindex="0"><thead><tr><th style="text-align:left;">函数</th><th style="text-align:left;">说明</th></tr></thead><tbody><tr><td style="text-align:left;"><code>int abs(int x)</code></td><td style="text-align:left;">求整型 <code>x</code> 的绝对值</td></tr><tr><td style="text-align:left;"><code>long labs(long x)</code></td><td style="text-align:left;">求长整型 <code>x</code> 的绝对值</td></tr><tr><td style="text-align:left;"><code>long long llabs(long long x)</code></td><td style="text-align:left;">求长整型 <code>x</code> 的绝对值</td></tr><tr><td style="text-align:left;"><code>double fabs(double x)</code></td><td style="text-align:left;">求双精度浮点数 <code>x</code> 的绝对值</td></tr></tbody></table><h4 id="指数与对数" tabindex="-1">指数与对数 <a class="header-anchor" href="#指数与对数" aria-label="Permalink to &quot;指数与对数&quot;">​</a></h4><table tabindex="0"><thead><tr><th style="text-align:left;">函数</th><th style="text-align:left;">说明</th></tr></thead><tbody><tr><td style="text-align:left;"><code>double exp(double x)</code></td><td style="text-align:left;">求 <code>e^x</code>（自然对数的底数 e 的 x 次幂）</td></tr><tr><td style="text-align:left;"><code>double exp2(double x)</code></td><td style="text-align:left;">求 <code>2^x</code></td></tr><tr><td style="text-align:left;"><code>double log(double x)</code></td><td style="text-align:left;">求 <code>x</code> 的自然对数（以 e 为底），<code>x &gt; 0</code></td></tr><tr><td style="text-align:left;"><code>double log10(double x)</code></td><td style="text-align:left;">求 <code>x</code> 的常用对数（以 10 为底），<code>x &gt; 0</code></td></tr><tr><td style="text-align:left;"><code>double log2(double x)</code></td><td style="text-align:left;">求 <code>x</code> 的以 2 为底的对数，<code>x &gt; 0</code></td></tr></tbody></table><h4 id="幂与根" tabindex="-1">幂与根 <a class="header-anchor" href="#幂与根" aria-label="Permalink to &quot;幂与根&quot;">​</a></h4><table tabindex="0"><thead><tr><th style="text-align:left;">函数</th><th style="text-align:left;">说明</th></tr></thead><tbody><tr><td style="text-align:left;"><code>double sqrt(double x)</code></td><td style="text-align:left;">求 <code>x</code> 的平方根，<code>x &gt;= 0</code></td></tr><tr><td style="text-align:left;"><code>double cbrt(double x)</code></td><td style="text-align:left;">求 <code>x</code> 的立方根</td></tr><tr><td style="text-align:left;"><code>double pow(double x, double y)</code></td><td style="text-align:left;">求 <code>x</code> 的 <code>y</code> 次幂</td></tr><tr><td style="text-align:left;"><code>double hypot(double x, double y)</code></td><td style="text-align:left;">求 <code>sqrt(x^2 + y^2)</code>（直角三角形斜边）</td></tr></tbody></table><h4 id="取整" tabindex="-1">取整 <a class="header-anchor" href="#取整" aria-label="Permalink to &quot;取整&quot;">​</a></h4><table tabindex="0"><thead><tr><th style="text-align:left;">函数</th><th style="text-align:left;">说明</th></tr></thead><tbody><tr><td style="text-align:left;"><code>double ceil(double x)</code></td><td style="text-align:left;">向上取整，返回不小于 <code>x</code> 的最小整数</td></tr><tr><td style="text-align:left;"><code>double floor(double x)</code></td><td style="text-align:left;">向下取整，返回不大于 <code>x</code> 的最大整数</td></tr><tr><td style="text-align:left;"><code>double round(double x)</code></td><td style="text-align:left;">四舍五入到最近的整数</td></tr><tr><td style="text-align:left;"><code>double trunc(double x)</code></td><td style="text-align:left;">向零取整，截断小数部分</td></tr></tbody></table><h4 id="三角函数-角度制为弧度" tabindex="-1">三角函数（角度制为弧度） <a class="header-anchor" href="#三角函数-角度制为弧度" aria-label="Permalink to &quot;三角函数（角度制为弧度）&quot;">​</a></h4><table tabindex="0"><thead><tr><th style="text-align:left;">函数</th><th style="text-align:left;">说明</th></tr></thead><tbody><tr><td style="text-align:left;"><code>double sin(double x)</code></td><td style="text-align:left;">正弦</td></tr><tr><td style="text-align:left;"><code>double cos(double x)</code></td><td style="text-align:left;">余弦</td></tr><tr><td style="text-align:left;"><code>double tan(double x)</code></td><td style="text-align:left;">正切</td></tr></tbody></table><h4 id="反三角函数" tabindex="-1">反三角函数 <a class="header-anchor" href="#反三角函数" aria-label="Permalink to &quot;反三角函数&quot;">​</a></h4><table tabindex="0"><thead><tr><th style="text-align:left;">函数</th><th style="text-align:left;">说明</th></tr></thead><tbody><tr><td style="text-align:left;"><code>double asin(double x)</code></td><td style="text-align:left;">反正弦，返回值范围 <code>[-π/2, π/2]</code></td></tr><tr><td style="text-align:left;"><code>double acos(double x)</code></td><td style="text-align:left;">反余弦，返回值范围 <code>[0, π]</code></td></tr><tr><td style="text-align:left;"><code>double atan(double x)</code></td><td style="text-align:left;">反正切，返回值范围 <code>[-π/2, π/2]</code></td></tr><tr><td style="text-align:left;"><code>double atan2(double y, double x)</code></td><td style="text-align:left;">求 <code>y/x</code> 的反正切，返回值范围 <code>[-π, π]</code>，可处理象限</td></tr></tbody></table><h4 id="双曲函数" tabindex="-1">双曲函数 <a class="header-anchor" href="#双曲函数" aria-label="Permalink to &quot;双曲函数&quot;">​</a></h4><table tabindex="0"><thead><tr><th style="text-align:left;">函数</th><th style="text-align:left;">说明</th></tr></thead><tbody><tr><td style="text-align:left;"><code>double sinh(double x)</code></td><td style="text-align:left;">双曲正弦</td></tr><tr><td style="text-align:left;"><code>double cosh(double x)</code></td><td style="text-align:left;">双曲余弦</td></tr><tr><td style="text-align:left;"><code>double tanh(double x)</code></td><td style="text-align:left;">双曲正切</td></tr><tr><td style="text-align:left;"><code>double asinh(double x)</code></td><td style="text-align:left;">反双曲正弦</td></tr><tr><td style="text-align:left;"><code>double acosh(double x)</code></td><td style="text-align:left;">反双曲余弦，<code>x &gt;= 1</code></td></tr><tr><td style="text-align:left;"><code>double atanh(double x)</code></td><td style="text-align:left;">反双曲正切，<code>-1 &lt; x &lt; 1</code></td></tr></tbody></table><h4 id="其他常用函数" tabindex="-1">其他常用函数 <a class="header-anchor" href="#其他常用函数" aria-label="Permalink to &quot;其他常用函数&quot;">​</a></h4><table tabindex="0"><thead><tr><th style="text-align:left;">函数</th><th style="text-align:left;">说明</th></tr></thead><tbody><tr><td style="text-align:left;"><code>double fmod(double x, double y)</code></td><td style="text-align:left;">浮点数取模，返回 <code>x</code> 除以 <code>y</code> 的余数</td></tr><tr><td style="text-align:left;"><code>double remainder(double x, double y)</code></td><td style="text-align:left;">返回 <code>x</code> 除以 <code>y</code> 的余数（舍入到最接近的整数）</td></tr><tr><td style="text-align:left;"><code>double copysign(double x, double y)</code></td><td style="text-align:left;">返回 <code>x</code> 的绝对值，符号与 <code>y</code> 相同</td></tr></tbody></table><h4 id="常用常量-c-20" tabindex="-1">常用常量(C++20) <a class="header-anchor" href="#常用常量-c-20" aria-label="Permalink to &quot;常用常量(C++20)&quot;">​</a></h4><table tabindex="0"><thead><tr><th style="text-align:left;">常量</th><th style="text-align:left;">说明</th></tr></thead><tbody><tr><td style="text-align:left;"><code>M_PI</code></td><td style="text-align:left;">圆周率 π（非标准，GCC 可用）</td></tr><tr><td style="text-align:left;"><code>M_E</code></td><td style="text-align:left;">自然对数的底数 e（非标准，GCC 可用</td></tr></tbody></table><p><strong>注意</strong>：</p><ul><li>所有三角函数和反三角函数的参数和返回值均为<strong>弧度</strong>，不是角度。</li><li>角度转弧度：<code>rad = deg * M_PI / 180.0</code></li><li>弧度转角度：<code>deg = rad * 180.0 / M_PI</code></li></ul>',22)])])}const g=e(a,[["render",c]]);export{y as __pageData,g as default};
